function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(100 + i * 150 + 50 * Math.sin(t + i), 100 + 20 * Math.sin(t + i * 2), 20 + 10 * Math.sin(t + i * 3), 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // trees
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(200, H - 50);
  ctx.lineTo(200, H - 150 - 50 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(250, H - 50);
  ctx.lineTo(250, H - 120 - 30 * Math.sin(t + 1));
  ctx.stroke();

  // birds
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(300 + 50 * Math.sin(t), 150 + 20 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(300 + 50 * Math.sin(t), 160 + 20 * Math.cos(t));
  ctx.lineTo(310 + 50 * Math.sin(t), 170 + 20 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
